const date = $('Set operating context').first().json.operating_date;
const pattern = new RegExp(`^pos_${date}_(?:S-)?(\\d{1,3})\\.csv$`, 'i');
const files = $input.all().map(item => item.json).filter(file => file?.id);
const csvFiles = files.filter(file => file.name?.toLowerCase().endsWith('.csv'));
const unexpected = csvFiles.filter(file => !pattern.test(file.name));
if (unexpected.length) throw new Error(`CSV con nombre invalido: ${unexpected.map(file => file.name).join(', ')}. Usa pos_${date}_S-XX.csv.`);
const candidates = csvFiles.map(file => {
  const match = file.name.match(pattern);
  return match ? { ...file, operating_date: date, branch_code: `S-${match[1].padStart(2, '0')}`, expected_sucursal_id: String(Number(match[1])) } : null;
}).filter(Boolean);
if (!candidates.length) throw new Error(`No hay CSVs para procesar en input/${date}/. Se esperaba pos_${date}_S-XX.csv.`);
return candidates.map(json => ({ json }));

const required = ['venta_id', 'fecha_hora', 'sucursal_id', 'producto_id', 'cantidad', 'precio_unitario', 'medio_pago', 'canal'];
const rows = $input.all().map(item => item.json);
const source = $('Loop daily branch CSVs').item.json;
const date = source.operating_date;
const errors = [];
const normalizarClave = (value) =>
  String(value ?? '')
    .trim()
    .replace(/\s+/g, ' ')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase();

const mediosPago = new Map([
  ['efectivo', 'Efectivo'],
  ['mercado pago', 'Mercado Pago'],
  ['tarjeta de credito', 'Tarjeta de crédito'],
  ['tarjeta credito', 'Tarjeta de crédito'],
  ['tarjeta de debito', 'Tarjeta de débito'],
  ['tarjeta debito', 'Tarjeta de débito'],
]);

const canales = new Map([
  ['salon', 'Salón'],
  ['local', 'Salón'],
  ['take away', 'Take Away'],
  ['takeaway', 'Take Away'],
  ['delivery', 'Delivery'],
]);

function valorCanonico(value, mapa, field, row) {
  const original = String(value ?? '').trim();

  if (!original) return null;

  if (original.includes('\uFFFD')) {
    errors.push({ row, code: 'invalid_encoding', field, received: original });
    return null;
  }

  const normalizado = mapa.get(normalizarClave(original));

  if (!normalizado) {
    errors.push({ row, code: 'invalid_value', field, received: original });
    return null;
  }

  return normalizado;
}
const sales = new Map();
const lines = [];
if (!rows.length) errors.push({ code: 'empty_csv' });
for (let i = 0; i < rows.length; i++) {
  const r = rows[i]; const row = i + 2;
  for (const column of required) if (r[column] === undefined || String(r[column]).trim() === '') errors.push({ row, code: 'missing_field', field: column });
  const qty = Number(r.cantidad), price = Number(r.precio_unitario);
  if (!(qty > 0)) errors.push({ row, code: 'invalid_quantity' });
  if (!(price >= 0)) errors.push({ row, code: 'invalid_price' });
  if (!String(r.fecha_hora || '').startsWith(date)) errors.push({ row, code: 'outside_operating_date' });
  if (String(r.sucursal_id || '').trim() !== source.expected_sucursal_id) errors.push({ row, code: 'branch_does_not_match_filename', expected: source.expected_sucursal_id, received: String(r.sucursal_id || '').trim() });
  const medio_pago = valorCanonico(r.medio_pago, mediosPago, 'medio_pago', row);
  const canal = valorCanonico(r.canal, canales, 'canal', row);
  if (errors.some(error => error.row === row)) continue;
  const venta_id = String(r.venta_id).trim();
  const fecha_hora = `${String(r.fecha_hora).trim().replace(' ', 'T')}-03:00`;
  const subtotal = Math.round(qty * price * 100) / 100;
  const linea_id = lines.filter(line => line.venta_id === venta_id).length + 1;
  lines.push({
  venta_id,
  linea_id,
  fecha_hora,
  sucursal_id: String(r.sucursal_id).trim(),
  producto_id: String(r.producto_id).trim(),
  cantidad: qty,
  precio_unitario: price,
  subtotal,
  medio_pago,
  canal,
});
} // cierra: for (let i = 0; i < rows.length; i++)
for (const line of lines) {
  const old = sales.get(line.venta_id);
  const identity = { fecha_hora: line.fecha_hora, sucursal_id: line.sucursal_id, medio_pago: line.medio_pago, canal: line.canal };
  if (old && JSON.stringify(old.identity) !== JSON.stringify(identity)) errors.push({ code: 'inconsistent_sale_header', venta_id: line.venta_id });
  else sales.set(line.venta_id, { ...old, identity, total_venta: (old?.total_venta || 0) + line.subtotal });
}
if (errors.length) return [{ json: { valid: false, source_file_id: source.id, source_file_name: source.name, operating_date: date, branch_code: source.branch_code, errors } }];
return [{ json: { valid: true, source_file_id: source.id, source_file_name: source.name, operating_date: date, branch_code: source.branch_code, lines, sales: [...sales].map(([venta_id, sale]) => ({ venta_id, ...sale.identity, total_venta: Math.round(sale.total_venta * 100) / 100 })) } }];

const validation = $('Validate and derive batch').item.json;
const source = $('Loop daily branch CSVs').item.json;
const date = source.operating_date;
const dbResult = $json.status ? { status: $json.status, batch_id: $json.batch_id, message: $json.message } : null;
const report = { generated_at: $now.setZone('America/Argentina/Buenos_Aires').toISO(), operating_date: date, branch: source.branch_code, source_file: { id: source.id, name: source.name }, validation_errors: validation.errors ?? [], database_result: dbResult };
return [{ json: { error_file_name: `errores_${date}_${source.branch_code}.json`, error_file_content: JSON.stringify(report, null, 2) } }];
